async function hydrateImages(root){for(const image of root.querySelectorAll('.sample-picture>img')){const missing=()=>{if(!image.isConnected)return;const frame=image.parentElement;frame.textContent='샘플 사진을 불러오지 못했어요.';frame.classList.add('photo-unavailable');frame.setAttribute('aria-label','샘플 사진을 불러오지 못했어요.');};image.onerror=missing;if(image.complete&&!image.naturalWidth)missing();}for(const img of root.querySelectorAll('img[data-photo-id]')){const id=img.dataset.photoId;try{let cached=photoUrls.get(id);if(!cached){const record=await getPhotoRecord(id);if(!record)throw new Error('사진이 없어요.');if(!img.isConnected)continue;cached=photoUrls.get(id);if(!cached){const originalUrl=URL.createObjectURL(record.originalBlob);cached={originalUrl,url:record.stickerBlob?URL.createObjectURL(record.stickerBlob):originalUrl,sticker:!!record.stickerBlob};photoUrls.set(id,cached);}}if(!img.isConnected)continue;img.src=cached.url;img.classList.toggle('is-sticker',cached.sticker);if(img.classList.contains('sheet-photo')){const body=img.closest('.sheet-body'),toggle=body.querySelector('[data-photo-toggle]'),note=body.querySelector('[data-photo-method]');if(note&&cached.sticker)note.textContent=(id.startsWith('sample-')?'합성 예시 사진을':'선택한 사진을')+' 기기 안에서 실제 AI로 배경 제거한 결과입니다. 원래 사진은 축소본으로 함께 보관했어요.';if(toggle){toggle.hidden=!cached.sticker;toggle.onclick=()=>{const original=img.dataset.variant!=='original';img.dataset.variant=original?'original':'sticker';img.src=original?cached.originalUrl:cached.url;img.classList.toggle('is-sticker',!original);toggle.textContent=original?'스티커 보기':'원래 사진 보기';};}}}catch(error){if(img.isConnected){const msg=document.createElement('p');msg.className='photo-missing';msg.textContent='사진을 불러오지 못했어요. 기록 정보는 남아 있어요.';img.replaceWith(msg);}}}}
