function openMember(id){const group=state.groups.find(g=>g.id===ui.groupId);if(!group||!membersOf(group).includes(id))return;const profile=memberProfile(id),visible=revealedProfile(profile,group.stage);openSheet(`${profile.nickname}의 접힌 소개`,`${friend()}<p>${id==='self'?'내 소개':'가상 멤버'} · 이 조에서는 ${group.stage}단계까지 펼쳤어요.</p><dl class="sheet-details">${REVEAL_FIELDS.map((f,i)=>`<div><dt>${f.label}</dt><dd ${i>=group.stage?'class="locked"':''}>${i<group.stage?esc(visible[f.key]||'아직 적지 않았어'):`평일 ${i+1-group.stage}일 더 함께하면 펼쳐져요`}</dd></div>`).join('')}</dl><p class="image-note">공개 순서를 체험하는 데모입니다. 실제 다른 사용자의 정보가 아닙니다.</p>`);}
async function selectPhoto(file,sample=false){if(busy)return;cancelCutout();busy=true;ui.error='';notice('사진을 기기 안에서 줄이고 있어요.');render();try{const result=await compressPhoto(file);releasePhotoSelection();const originalUrl=URL.createObjectURL(result.blob);ui.photo={...result,originalBlob:result.blob,originalUrl,url:originalUrl,stickerBlob:null,stickerUrl:null,variant:'original',cutoutState:'idle',date:ui.trial?nextWeekday(state.today):state.today,sample};notice('사진 준비 완료. 이름과 이야기는 비워도 좋아요.');}catch(error){onError(error);}finally{busy=false;const focusId=document.activeElement.id;render();document.getElementById(focusId||'photo-pick')?.focus({preventScroll:true});}}
async function samplePhoto(){try{const response=await fetch('./assets/stickers.jpg');if(!response.ok)throw new Error('예시 조각을 불러오지 못했어요.');const bitmap=await createImageBitmap(await response.blob());const canvas=document.createElement('canvas');canvas.width=550;canvas.height=550;const date=ui.trial?nextWeekday(state.today):state.today;const n=sampleIndex(missionForDate(date,state.profile.campus));canvas.getContext('2d').drawImage(bitmap,(n%2)*bitmap.width/2,Math.floor(n/2)*bitmap.height/2,bitmap.width/2,bitmap.height/2,0,0,550,550);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.8));await selectPhoto(blob,true);}catch(error){onError(error);}}
