async function action(name){
 if(name==='setup-next'){ui.step++;render();}
 if(name==='setup-back'){ui.step=Math.max(1,ui.step-1);ui.error='';render();}
 if(name==='edit-profile'){ui.editing=true;ui.step=2;ui.draft={...state.profile};render();}
 if(name==='trial-start'){ui.trial=true;clearSelection();render();}
 if(name==='trial-exit'){ui.trial=false;clearSelection();render();}
 if(name==='sample-photo')await samplePhoto();
 if(name==='show-today-group'){const e=state.entries.find(x=>x.date===state.today);if(e)ui.groupId=e.groupId;route('groups');}
 if(name==='leave-group')confirmLeave();
 if(name==='reload')location.reload();
}
function confirmLeave(){const group=state.groups.find(g=>g.id===ui.groupId);if(!group)return;openSheet('이 조를 나갈까요?',`<div class="mascot-inline">${friend()}<p>${esc(group.name)}는<br>활성 목록에서 바로 사라져요.</p></div><p class="dialog-warning">내 사진과 당시 조 스탬프는 도감에 남아요. 이 샘플 조로 다시 돌아오지는 못해요.</p><div class="form-actions"><button class="secondary" id="confirm-cancel">조금 더 있을래요</button><button class="primary" id="confirm-leave">이 조 나가기</button></div><p id="dialog-error" class="error-note" role="alert"></p>`);document.querySelector('#confirm-cancel').onclick=closeSheet;document.querySelector('#confirm-leave').onclick=async()=>{try{await dispatch({type:'LEAVE_GROUP',groupId:group.id});closeSheet();ui.groupId=null;render();notice('이 조를 나왔어요. 내 도감은 그대로예요.');}catch(error){document.querySelector('#dialog-error').textContent=storageMessage(error);}};}
async function advanceDay(){if(ui.trial){ui.trial=false;clearSelection();}const date=nextWeekday(state.today);await dispatch({type:'ADVANCE_DATE',date,demo:true});ui.week=date;ui.page='today';ui.error='';clearSelection();render();notice(`${date} 데모 날짜로 넘어왔어요. 실제 매칭은 없어요.`);return summary();}
function demoMenu(){openSheet('작은 데모 서랍',`<p>현재 ${state.demoDate?'데모 날짜':'한국 실제 날짜'} · <strong>${state.today}</strong></p><p class="image-note">날짜를 넘기면 조 유지와 소개 공개도 함께 진행돼요. 이 데모 날짜는 새로고침 후에도 유지돼요. 실제 날짜로 시작하려면 초기화해 주세요.</p><div class="demo-options"><button class="secondary" id="advance-day" ${fatal?'disabled':''}>다음 평일로 이동 ${icon('arrow')}</button><label for="screen-width">화면 크기<select id="screen-width"><option value="">자동</option><option value="320">320px</option><option value="390">390px</option><option value="430">430px</option></select></label><label class="checks"><input id="large-text" type="checkbox" ${preview.classList.contains('large-text')?'checked':''}>글자 200% 미리보기</label><div class="wavy-divider"></div><button class="danger-link" id="reset-open">처음부터 다시 시작</button></div><p class="image-note">WebMCP: ${esc(registration)}. UI와 같은 상태 로직을 쓰며 사진·소개 값은 도구에 노출하지 않아요.</p><p id="dialog-error" class="error-note" role="alert"></p>`);const select=document.querySelector('#screen-width');select.value=preview.dataset.width||'';select.onchange=()=>{preview.dataset.width=select.value;preview.classList.toggle('compact',!!select.value);preview.style.maxWidth=select.value?select.value+'px':'';preview.style.setProperty('--preview-width',select.value?select.value+'px':'100%');document.documentElement.style.setProperty('--demo-width',select.value?select.value+'px':'100vw');closeSheet();};document.querySelector('#large-text').onchange=e=>{preview.classList.toggle('large-text',e.target.checked);document.documentElement.style.setProperty('--type-scale',e.target.checked?'2':'1');closeSheet();};document.querySelector('#advance-day').onclick=async()=>{try{await advanceDay();closeSheet();}catch(error){document.querySelector('#dialog-error').textContent=storageMessage(error);}};document.querySelector('#reset-open').onclick=confirmReset;}
function confirmReset(){openSheet('도감을 처음부터 펼칠까요?',`<p class="dialog-warning">이 브라우저에 저장한 모든 사진과 소개, 샘플 조와 대화를 지워요. 되돌릴 수 없어요.</p><p>다른 기기나 실제 학교 계정에는 영향을 주지 않아요.</p><div class="form-actions"><button class="secondary" id="reset-cancel">그대로 둘래요</button><button class="primary" id="reset-confirm">모두 지우고 다시 시작</button></div><p id="dialog-error" class="error-note" role="alert"></p>`);document.querySelector('#reset-cancel').onclick=closeSheet;document.querySelector('#reset-confirm').onclick=async()=>{if(busy)return;busy=true;document.querySelector('#reset-confirm').disabled=true;try{await resetStorage();state=createState(todaySeoul());fatal='';stale=false;setBanner('');ui.page='today';ui.step=1;ui.editing=false;ui.draft={campus:'자연과학캠퍼스'};ui.trial=false;ui.groupId=null;ui.week=null;ui.groupPanel='photos';ui.groupSettingsOpen=false;ui.chatDrafts.clear();ui.chatErrors.clear();ui.chatScroll.clear();clearSelection();for(const cached of photoUrls.values())for(const url of new Set([cached.url,cached.originalUrl]))URL.revokeObjectURL(url);photoUrls.clear();closeSheet();render();notice('이 브라우저의 도감을 비웠어요. 새 종이부터 시작해요.');}catch(error){document.querySelector('#dialog-error').textContent=storageMessage(error);document.querySelector('#reset-confirm').disabled=false;}finally{busy=false;}};}
function summary(){return {app:'skkugit',mode:'local-demo',page:ui.page,date:state.today,demoClock:!!state.demoDate,onboarded:!!state.profile,stateReadable:!fatal,needsReload:stale,entryCount:fatal?null:state.entries.length,groups:fatal?null:activeGroups().map(g=>({id:g.id,stage:g.stage,daysTogether:g.daysTogether,members:membersOf(g).length,keep:g.keep})),containsPersonalValues:false};}
async function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool){registration='이 브라우저에서 미지원 · 기본 UI는 정상 작동';return;}
 const tools=[{name:'skkugit_get_state',description:'Read only counts, demo date and reveal stages. Does not expose photos or profile values.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>JSON.stringify(summary())},{name:'skkugit_navigate',description:'Navigate the local skkugit demo to a main screen. Does not submit forms.',inputSchema:{type:'object',properties:{page:{type:'string',enum:pages.map(p=>p[0])}},required:['page'],additionalProperties:false},execute:async({page})=>{if(!pages.some(p=>p[0]===page))throw new Error('Invalid page');route(page);return JSON.stringify(summary());}},{name:'skkugit_next_weekday',description:'Advance the local demo clock to the next weekday using the same action as the Demo menu. This changes local sample groups, not real users.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async()=>JSON.stringify(await advanceDay())}];
 try{for(const tool of tools)await ctx.registerTool(tool);registration='기본 액션 3개 등록됨';}catch{registration='API 등록 불가 · 기본 UI는 정상 작동';}}
async function checkClock(){if(state.demoDate||fatal||busy)return;const now=todaySeoul();if(now>state.today){cancelCutout();try{await dispatch({type:'ADVANCE_DATE',date:now});render();}catch(error){setBanner(storageMessage(error));}}}

